package ec.edu.unl.sec.selfassessment.api;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import ec.edu.unl.sec.selfassessment.application.*;import ec.edu.unl.sec.selfassessment.domain.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.*;class SelfAssessmentControllerTest{MockMvc mvc;SelfAssessmentService service;@BeforeEach void setup(){service=mock(SelfAssessmentService.class);mvc=MockMvcBuilders.standaloneSetup(new SelfAssessmentController(service,mock(ProcessTransitionService.class))).setControllerAdvice(new ProcessExceptionHandler()).build();}@Test void returnsRevisionEtag()throws Exception{var p=new SelfAssessmentProcess(null,UUID.randomUUID(),"P","Proceso",LocalDate.now(),LocalDate.now(),UUID.randomUUID(),1,ProcessState.DRAFT,0,UUID.randomUUID(),Instant.now(),List.of());when(service.get(p.id())).thenReturn(p);mvc.perform(get("/processes/"+p.id())).andExpect(status().isOk()).andExpect(header().string("ETag","\"0\""));}}
